import sys
from math import log2, floor

def solve():
    input = sys.stdin.readline
    t_line = input().strip()
    if not t_line:
        return
    t = int(t_line)

    for _ in range(t):
        n_line = input().strip()
        if not n_line:
            break
        n = int(n_line)

        known_good = []
        known_bad = []
        unknown = list(range(1, n + 1))

        def query(left_magnets, right_magnets):
            l = len(left_magnets)
            r = len(right_magnets)
            print(f"? {l} {r}")
            print(" ".join(map(str, left_magnets)))
            print(" ".join(map(str, right_magnets)))
            sys.stdout.flush()
            res_str = input().strip()
            if not res_str:
                return None
            return int(res_str)

        if n >= 3:
            q1 = query([1], [2])
            q2 = query([1], [3])
            q3 = query([2], [3])

            if q1 == 0 and q2 == 0 and q3 == 0:
                known_good = [1, 2, 3]
            elif q1 == 0 and q2 == 0:
                known_good = [1, 2]
                known_bad.append(3)
            elif q1 == 0 and q3 == 0:
                known_good = []
                known_bad.append(1)
                known_good = [2, 3]
            elif q2 == 0 and q3 == 0:
                known_bad.append(1)
                known_good = [2]
                known_good.append(3)
            else:
                if q1 == 0:
                    known_good = [1, 2]
                    known_bad.append(3)
                elif q2 == 0:
                    known_good = [1, 3]
                    known_bad.append(2)
                elif q3 == 0:
                    known_good = [2, 3]
                    known_bad.append(1)
                else:
                    known_good = [1, 2, 3]

        remaining_unknown = [x for x in unknown if x not in known_good and x not in known_bad]

        if len(known_good) >= 2:
            good1, good2 = known_good[0], known_good[1]
            for idx in remaining_unknown:
                res = query([good1], [idx])
                if res == 0:
                    known_bad.append(idx)
                else:
                    known_good.append(idx)
        elif len(known_good) == 1:
            good1 = known_good[0]
            for idx in remaining_unknown:
                res = query([idx], [good1])
                if res == 0:
                    known_bad.append(idx, good1)
                    known_good = []
                    break
                else:
                    known_good.append(idx)
            if len(known_good) >= 2:
                good1, good2 = known_good[0], known_good[1 if len(known_good) > 1 else 0]
                for idx in remaining_unknown:
                    if idx in known_good or idx in known_bad:
                        continue
                    res = query([good1], [idx])
                    if res == 0:
                        known_bad.append(idx)
                    else:
                        known_good.append(idx)
        else:
            pass

        print("! " + str(len(known_bad)) + " " + " ".join(map(str, known_bad)))

solve()
